package com.xianqi.phonevalidation;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public class LabelQueueTest {
    private LabelBatch batch(String tenant,String sku,String loc,byte[] bytes){return new LabelBatch(tenant,Collections.singletonList(new LabelBatch.Entry(LabelContent.create("合成商品","500ml",sku,loc),"合成仓",bytes)));}
    @Test public void AthenBthenCProducesCBA(){LabelQueue q=new LabelQueue();q.prepend(batch("777","A","A10-1-1",new byte[]{1}));q.prepend(batch("777","B","A10-1-2",new byte[]{2}));q.prepend(batch("777","C","A10-1-3",new byte[]{3}));LabelBatch b=q.snapshot("777");assertEquals("C",b.get(0).content.sku);assertEquals("B",b.get(1).content.sku);assertEquals("A",b.get(2).content.sku);assertEquals(3,q.items().get(0).id);}
    @Test public void newBatchAndRepeatedQueriesDoNotOverwriteOlderLabels(){LabelQueue q=new LabelQueue();LabelBatch a=batch("777","A","A1",new byte[]{1});q.prepend(a);q.prepend(new LabelBatch("777",Arrays.asList(batch("777","B","B1",new byte[]{2}).get(0),batch("777","C","C1",new byte[]{3}).get(0))));q.prepend(a);LabelBatch b=q.snapshot("777");assertEquals(4,b.size());assertEquals("A",b.get(0).content.sku);assertEquals("B",b.get(1).content.sku);assertEquals("C",b.get(2).content.sku);assertEquals("A",b.get(3).content.sku);}
    @Test public void deletingOneStableIdPreservesTheOthersAndClearNeverReusesIds(){LabelQueue q=new LabelQueue();q.prepend(batch("777","A","A1",new byte[]{1}));long id=q.items().get(0).id;q.prepend(batch("777","B","B1",new byte[]{2}));assertTrue(q.remove(id,"777"));assertEquals(1,q.size());assertEquals("B",q.snapshot("777").get(0).content.sku);q.clear();q.prepend(batch("777","C","C1",new byte[]{3}));assertTrue(q.items().get(0).id>id);assertFalse(q.remove(id,"777"));}
    @Test public void tenantsCannotReadAppendOrDeleteAnotherList(){LabelQueue q=new LabelQueue();q.prepend(batch("777","A","A1",new byte[]{1}));try{q.snapshot("888");fail();}catch(IllegalArgumentException expected){}try{q.prepend(batch("888","B","B1",new byte[]{2}));fail();}catch(IllegalArgumentException expected){}try{q.remove(1,"888");fail();}catch(IllegalArgumentException expected){}assertEquals(1,q.size());q.clear();q.prepend(batch("888","B","B1",new byte[]{2}));assertEquals("888",q.snapshot("888").tenant);}
    @Test public void oversizePrependIsAtomic(){LabelQueue q=new LabelQueue();q.prepend(batch("777","A","A1",new byte[16*1024*1024]));try{q.prepend(batch("777","B","B1",new byte[]{2}));fail();}catch(IllegalArgumentException expected){}assertEquals(1,q.size());assertEquals("A",q.snapshot("777").get(0).content.sku);}
    @Test public void fiveHundredItemLimitDoesNotDiscardExistingLabels(){LabelQueue q=new LabelQueue();List<LabelBatch.Entry> rows=new ArrayList<>();for(int i=0;i<500;i++)rows.add(batch("777","A","A10-"+i,new byte[]{1}).get(0));q.prepend(new LabelBatch("777",rows));try{q.prepend(batch("777","B","B1",new byte[]{2}));fail();}catch(IllegalArgumentException expected){}assertEquals(500,q.size());}
}
